window.ScripturaLexicons.BDAG_PART_0330 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-01\" data-source=\"BDAG\" data-search=\"στασιαστής, οῦ, ὁ substantivo masculino rebelde; revolucionário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στασιαστής, οῦ, ὁ</td><td>substantivo masculino</td><td>rebelde; revolucionário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-02\" data-source=\"BDAG\" data-search=\"στάσις, εως, ἡ substantivo feminino existência; revolta; discórdia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στάσις, εως, ἡ</td><td>substantivo feminino</td><td>existência; revolta; discórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-03\" data-source=\"BDAG\" data-search=\"στατήρ, ῆρος, ὁ substantivo masculino estáter BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στατήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>estáter</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-04\" data-source=\"BDAG\" data-search=\"Στάτιος, ου, ὁ substantivo masculino; nome próprio Estácio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στάτιος, ου, ὁ</td><td>substantivo masculino; nome próprio</td><td>Estácio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-05\" data-source=\"BDAG\" data-search=\"στατίων, ωνος substantivo feminino; raramente masculino posto; estação; observância de jejum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στατίων, ωνος</td><td>substantivo feminino; raramente masculino</td><td>posto; estação; observância de jejum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-06\" data-source=\"BDAG\" data-search=\"σταυρίσκω verbo crucificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταυρίσκω</td><td>verbo</td><td>crucificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-07\" data-source=\"BDAG\" data-search=\"σταυρός, οῦ, ὁ substantivo masculino cruz; sofrimento ou morte por seguir Cristo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταυρός, οῦ, ὁ</td><td>substantivo masculino</td><td>cruz; sofrimento ou morte por seguir Cristo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-08\" data-source=\"BDAG\" data-search=\"σταυρόω verbo crucificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταυρόω</td><td>verbo</td><td>crucificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-09\" data-source=\"BDAG\" data-search=\"σταφυλή, ῆς, ἡ substantivo feminino uva; cacho de uvas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σταφυλή, ῆς, ἡ</td><td>substantivo feminino</td><td>uva; cacho de uvas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-10\" data-source=\"BDAG\" data-search=\"στάχυς, υος, ὁ substantivo masculino espiga; flor do nardo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στάχυς, υος, ὁ</td><td>substantivo masculino</td><td>espiga; flor do nardo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-11\" data-source=\"BDAG\" data-search=\"Στάχυς, υος, ὁ substantivo masculino; nome próprio Estáquis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στάχυς, υος, ὁ</td><td>substantivo masculino; nome próprio</td><td>Estáquis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-12\" data-source=\"BDAG\" data-search=\"στέαρ, ατος, τό substantivo neutro gordura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέαρ, ατος, τό</td><td>substantivo neutro</td><td>gordura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-13\" data-source=\"BDAG\" data-search=\"στέγη, ης, ἡ substantivo feminino teto; telhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέγη, ης, ἡ</td><td>substantivo feminino</td><td>teto; telhado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-14\" data-source=\"BDAG\" data-search=\"στέγος, ους, τό substantivo neutro teto; telhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέγος, ους, τό</td><td>substantivo neutro</td><td>teto; telhado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-15\" data-source=\"BDAG\" data-search=\"στέγω verbo guardar em segredo; encobrir; suportar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέγω</td><td>verbo</td><td>guardar em segredo; encobrir; suportar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-16\" data-source=\"BDAG\" data-search=\"στεῖρα, ας, ἡ adjetivo feminino; substantivado estéril; infértil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στεῖρα, ας, ἡ</td><td>adjetivo feminino; substantivado</td><td>estéril; infértil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-17\" data-source=\"BDAG\" data-search=\"στέλλω verbo afastar-se; evitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέλλω</td><td>verbo</td><td>afastar-se; evitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-18\" data-source=\"BDAG\" data-search=\"στέμμα, ατος, τό substantivo neutro grinalda; guirlanda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέμμα, ατος, τό</td><td>substantivo neutro</td><td>grinalda; guirlanda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-19\" data-source=\"BDAG\" data-search=\"στεναγμός, οῦ, ὁ substantivo masculino suspiro; gemido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στεναγμός, οῦ, ὁ</td><td>substantivo masculino</td><td>suspiro; gemido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0330-20\" data-source=\"BDAG\" data-search=\"στενάζω verbo suspirar; gemer; queixar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στενάζω</td><td>verbo</td><td>suspirar; gemer; queixar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0330-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στασιαστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στασιαστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">στασιάζω</span>; Diod S 10, 11, 1; Dionys. Hal. 6, 70, 1; Jos., Bell. 6, 157, Ant. 14, 8; PSI 442, 4 [III a.C.]) pessoa facciosa que provoca discórdia pública, rebelde, revolucionário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a>.—DELG s.v. <span class=\"greek\">στάσις</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στάσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στάσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span></p><p class=\"entry-text\">① condição de estar em certa posição ou estado de coisas, existência, ocorrência <span class=\"greek\">στάσιν</span> <span class=\"greek\">ἔχειν</span> existir, estar de pé (Polyb. 5, 5, 3; Plut., Mor. 731b <span class=\"greek\">ἔχ</span>. <span class=\"greek\">γένεσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">στάσιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:8</a> (também provavelmente lugar, posição [Hdt. 9, 24 al.; Diod S 12, 72, 10; 13, 50, 9; LXX; En 12:4]). A estabilidade era uma preocupação dominante na administração de um Estado. Se o foco recai sobre o processo que conduz ao estabelecimento de uma posição, a mudança é um componente dominante, daí</p><p class=\"entry-text\">② movimento em direção a um (novo) estado de coisas, insurreição, motim, revolta, rebelião (op. <span class=\"greek\">ἡσυχία</span> [q.v. 1] harmonia civil, conduta pacífica; desde Alcaeus 46a, 1 D.2 [<span class=\"greek\">ἀνέμων</span> <span class=\"greek\">στάσις</span>=tumulto dos ventos]; Aeschyl., Hdt.; Sb 6643, 18 [88 a.C.]; PLond VI, 1912, 73 [41 d.C.]; Philo; Jos., Ant. 20, 117; Tat. 19, 3; empréstimo na linguagem rabínica) contra a autoridade civil <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:19</a> (de uma insurreição: Dio Chrys. 21 [38], 14 <span class=\"greek\">γενομένης</span> <span class=\"greek\">στάσεως</span>), 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:40</a>. Contra os dirigentes de uma congregação cristã 1 Cl 1:1. Com <span class=\"greek\">διχοστασία</span> 51:1. Mas é difícil distinguir em 1 Cl entre este sentido e o seguinte, com foco no componente de discórdia.</p><p class=\"entry-text\">③ falta de acordo quanto à orientação a seguir, contenda, discórdia, desunião (Diod S 12, 14, 3 <span class=\"greek\">στάσεις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκίαις</span>; Appian, Bell. Civ. 4, 45 §193 <span class=\"greek\">ἡ</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἀντωνίου</span> <span class=\"greek\">στάσις</span>; IG IV2/1, 687, 13; PStras 20, 10; Jos., Ant. 18, 374 al.; Tat. 16, 3) 1 Cl 46:9. Com <span class=\"greek\">ἔρις</span> 3:2; 14:2 (<span class=\"greek\">στάσεις</span>). Com <span class=\"greek\">ἔρις</span> e <span class=\"greek\">σχίσματα</span> 54:2. Com <span class=\"greek\">σχίσμα</span> 2:6. Com <span class=\"greek\">ζήτησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:2</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καταβολὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ποιεῖν</span> lançar o fundamento da discórdia 1 Cl 57:1. <span class=\"greek\">ἡσυχάζειν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ματαίας</span> <span class=\"greek\">στ</span>. cessar essa dissensão inútil 63:1. Especif. de uma divergência de opinião, disputa (Aeschyl., Pers. 738; Apollon. Paradox. 6 <span class=\"greek\">τήν</span> <span class=\"greek\">γινομένην</span> <span class=\"greek\">στάσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Πυθαγορείοις</span> <span class=\"greek\">προειπεῖν</span>; Diog. L. 3, 51; Philo, Rer. Div. Her. 248; Jos., Vi. 143 <span class=\"greek\">γίνεται</span> <span class=\"greek\">στ</span>.; Tat. 1, 1 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:7</a>, 10 (Polyaenus, Exc. 40, 3 <span class=\"greek\">στάσεως</span> <span class=\"greek\">γενομένης</span>). <span class=\"greek\">κινεῖν</span> <span class=\"greek\">στάσεις</span> (v.l. <span class=\"greek\">στάσιν</span>) <span class=\"greek\">τισί</span> criar dissensão entre certas pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a>.—DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στατήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στατήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (como nome de moedas Aristoph., Hdt. et al.; inscr., pap., Aq., Sym., Jos., Ant. 7, 379; empréstimo na linguagem rabínica) o estáter, moeda de prata = quatro dracmas (c. quatro dias de salário) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:27</a> (v. OLZ 40, ’37, 665–70; JDerrett, Law in the NT, ’70, 248–52; NMc-Eleney, CBQ 38, ’76, 178–92); 26:15 v.l.—Lit. s.v. <span class=\"greek\">ἀργύριον</span> 2c.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στάτιος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στάτιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> Estácio, nome romano, <span class=\"greek\">Στάτιος</span> <span class=\"greek\">Κοδρᾶτος</span>, Estácio Quadrato, procônsul da Ásia na época do martírio de Policarpo MPol 21. A época em que exerceu o cargo é estimada de diversas maneiras; v. sobre <span class=\"greek\">Πολύκαρπος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στατίων, ωνος</h1><div class=\"entry-meta\"><span>substantivo feminino; raramente masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στατίων</span>, <span class=\"greek\">ωνος</span> (empréstimo lat. statio, encontrado também na linguagem rabínica, usado com vários sentidos em Strabo 17, 3, 2, 826; inscr. [OGI index VIII p. 704b; Hahn 227, 14]; BGU 326 II, 10; PRyl 78, 23; O. Wilck I 294f.—V. OGI 595 n. 4; JSvennung, ZNW 32, ’33, 294–308), <span class=\"greek\">ἡ</span> e raramente <span class=\"greek\">ὁ</span> (OGI 755, 4) prim. ‘estado ou posição de serviço de guarda, posto, estação’ <span class=\"greek\">στατίωνα</span> <span class=\"greek\">ἔχειν</span>= lat. stationem habere = ‘fazer serviço de guarda, estar de sentinela’; isto tornou-se parte do vocabulário eclesiástico (Lampe s.v.) e em sentido transf. observar um jejum (cf. Tertullian, Jejun. 13, Orat. 19, Fuga 1, Ad Uxorem 2, 4) Hs 5, 1, 1f (Leutzsch, Hermas 470 n. 51).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταυρίσκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταυρίσκω</span> (<span class=\"greek\">σταυρός</span>) crucificar <span class=\"greek\">τινά</span> alguém GPt 2:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταυρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταυρός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom. et al. no sentido de ‘estaca ereta e pontiaguda’ ou ‘estaca de paliçada’; v. Iren. 1, 2, 4 cj. [Harv. I, 18, 4]; como nome de um éon Hippol., Ref. 6, 31, 6)</p><p class=\"entry-text\">① poste destinado a ser fincado no solo e empregado para a pena capital, cruz (Diod S 2, 18, 1; Plut. et al.; Epict. 2, 2, 20; Diog. L. 6, 45; ApcEsdr 7:1 p. 32, 8 Tdf.; AscIs 3:18; Philo, In Flacc. 84; Jos., Ant. 11, 261; 266f.; Just.; v. também CSchneider, TW III 414, 4 e JCollins, The Archeology of the Crucifixion, CBQ 1, ’39, 154–59; JBlinzler, Der Prozess Jesu3, ’60, 278–81; EDinkler, Signum Crucis ’67; JFitzmyer, CBQ 40, ’78, 493–513), uma estaca fincada na terra em posição vertical; uma travessa era freq. fixada à sua parte superior (Artem. 2, 53), de modo que tinha a forma de um T ou a seguinte: †—MHengel, Crucifixion ’77. Lit., com outros meios de execução (Diogenes, Ep. 28, 3) IRo 5:3; Hv 3, 2, 1. Usada no caso de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:40</a>, 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:30</a>, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a>, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:8</a> (Just., D. 134, 5); GPt 4:11; 10:39, 42. <span class=\"greek\">ὑπομένειν</span> <span class=\"greek\">σταυρόν</span> submeter-se à cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>. Os condenados carregavam suas cruzes até o lugar da execução (Plut., Mor. 554a <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">κακούργων</span> <span class=\"greek\">ἐκφέρει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σταυρόν</span>; Chariton 4, 2, 7 <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">ἔφερε</span>; Artem. 2, 56.—Pauly-W. IV 1731) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:17</a>; nos sinóticos, Simão de Cirene foi obrigado a carregar a cruz de Jesus (<span class=\"greek\">Σίμων</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:26</a>. Uma inscrição na cruz indicava o motivo da execução <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:19</a> (v. <span class=\"greek\">τίτλος</span>).—WMichaelis, Zeichen, Siegel, Kreuz, TZ 12, ’56, 505–25. B procura mostrar em várias passagens que, segundo as Escrituras, era necessário que o Messias morresse na cruz: 8:1 (o <span class=\"greek\">ξύλον</span> que desempenha um papel em conexão com a novilha vermelha, Num 19:6, é <span class=\"greek\">ὁ</span> <span class=\"greek\">τύπος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>); 9:8 (no caso dos 318 servos de Abraão Gen 14:14, o número 300 [=<span class=\"greek\">Τ</span> ´] aponta para a cruz; cf. Lucian, Jud. Voc. 12: a letra tau tem a forma do <span class=\"greek\">σταυρός</span>); 11:1, 8a (o <span class=\"greek\">ξύλον</span> de Ps 1:3); 12:1 (cit. das Escrituras de origem incerta), 2.</p><p class=\"entry-text\">② a cruz, com foco no destino de Jesus Cristo, a cruz. A cruz de Cristo é um dos elementos mais importantes do culto e da proclamação cristãos: com morte e ressurreição IPhld 8:2 e outros pormenores de sua vida PtK 4 p. 15, 33. Para os judeus um <span class=\"greek\">σκάνδαλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:11</a> (cf. Dt 21:23); cf. IEph 18:1. Daí uma ocasião de perseguição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a> (<span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span> por causa da cruz; dat. de causa, v. <span class=\"greek\">ἀπιστία</span> 1). Mas para Paulo era seu único motivo de gloriar-se v. 14. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> a mensagem da cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:18</a>, com seu caráter misterioso e paradoxal, é necessariamente loucura para os incrédulos. Por essa razão, qualquer tentativa de apresentar essa mensagem sob a forma de sabedoria mundana privaria o <span class=\"greek\">σταυρὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> de seu verdadeiro conteúdo v. 17. <span class=\"greek\">τὸ</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> é o testemunho prestado pela Paixão ao fato da existência corpórea de Cristo Pol 7:1 (cf. Just., D. 40, 3 <span class=\"greek\">πάθος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>).—A morte de Cristo na cruz traz salvação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a>. <span class=\"greek\">εἰρηνοποιεῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <span class=\"greek\">αὐτοῦ</span> fazer a paz mediante o derramamento de seu sangue na cruz 1:20 (v. W-S. §30, 12c; Rob. 226). Por isso podemos <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">ἐλπίζειν</span> B 11:8b. Paulo conhece cristãos batizados aos quais se vê constrangido a chamar <span class=\"greek\">ἐχθροὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> por causa de seu modo de vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:18</a>. Por outro lado, Ign. fala de cristãos irrepreensíveis <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">καθηλωμένους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">σαρκί</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματι</span> como se estivessem pregados à cruz do Senhor Jesus Cristo tanto na carne como no espírito ISm 1:1 (cf. MartAndr Prius 1, 14 [Aa II/1, 54–55]). Na linguagem figurada de Ign., a cruz é chamada <span class=\"greek\">ἡ</span> <span class=\"greek\">μηχανὴ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. IEph 9:1 (v. HSchlier, Relgesch. Untersuchungen zu d. Ign.-briefen 1929, 110–24), e os crentes ortodoxos são os <span class=\"greek\">κλάδοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> ramos da cruz ITr 11:2. Tais passagens estabelecem uma ligação com o sentido transf.</p><p class=\"entry-text\">③ o sofrimento/a morte que os crentes suportam ao seguir o Senhor crucificado, cruz <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:38</a>. <span class=\"greek\">ἆραι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">στ</span>. <span class=\"greek\">αὐτοῦ</span> 16:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:34</a>; 10:21 t.r.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:23</a>. <span class=\"greek\">βαστάζειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ἑαυτοῦ</span> 14:27 (v. sobre estas passagens paralelas AFridrichsen, Festskrift for Lyder Brun 1922, 17–34.—EDinkler, Jesu Wort v. Kreuztragen: Bultmann Festschr. ’54, 110–29).—DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταυρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταυρόω</span> (<span class=\"greek\">σταυρός</span>; no sentido de ‘cercar com estacas’ Thu. et al.) fut. <span class=\"greek\">σταυρώσω</span>; 1 aor. <span class=\"greek\">ἐσταύρωσα</span>. Pass.: 1 aor. <span class=\"greek\">ἐσταυρώθην</span>; perf. <span class=\"greek\">ἐσταύρωμαι</span></p><p class=\"entry-text\">① fixar a uma cruz, crucificar (Polyb. 1, 86, 4; Diod S 16, 61, 2; Epict. 2, 2, 20; Artem. 2, 53; 4, 49; Esth 7:9; 8:12r; Jos., Ant. 2, 77; 17, 295). <span class=\"greek\">τινά</span> alguém com ref. à crucificação de Jesus (Orig., C. Cels. 4, 22, 9; v. TestSol 22:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:19</a>; 23:34; 26:2; 27:22f, 26, 31, 35, 38; 28:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:13ff</a>, 20, 24f, 27; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:21</a>, 23, 33; 24:7, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:6ab</a> (a duplicação do imperativo como Anaxarchus [IV a.C.] em Diog. L. 9, 59 <span class=\"greek\">πτίσσε</span>, <span class=\"greek\">πτίσσε</span>=esmaga, continua esmagando [num almofariz]), v. 6c, 10, 15f, 18, 20, 23, 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a>; 4:10; 13:29 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>; B 7:3, 9; 12:1; IEph 16:2; GPt 4:10; 12:52. <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ἐσταυρωμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:23</a>; cf. 2:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:1</a>. Também simplesmente <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐσταυρωμένος</span> MPol 17:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">σταυρωθείς</span> (Iren. 2, 32, 4 [Harv. I 375, 12]; Orig., C. Cels. 1, 31, 20) GPt 13:56. <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἐσταυρώθη</span> ele foi verdadeiramente crucificado (em contraste com a concepção docética de que a Paixão era irreal; Iren. 3, 19, 3 [Harv. II 104, 3]) ITr 9:1. (Sobre a crucificação de Jesus v. Feigel, Weidel e Finegan s.v. <span class=\"greek\">Ἰούδας</span> 6; também EBickermann, Utilitas Crucis: RHR 112, ’35, 169–241; sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:16</a>–32 como narrativa de crucificação à luz do triunfo romano v. TSchmidt, NTS 41, ’95, 1–18.).—<span class=\"greek\">μὴ</span> <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐσταυρώθη</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>; Foi Paulo crucificado por vós? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a>. <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">μέλλω</span> <span class=\"greek\">σταυροῦσθαι</span> devo ser crucificado mais uma vez AcPl Ha 7, 39 (cf. MartPt 6 [Aa I 88, 7; 8; 9; 12]). Este último oferece uma interessante transição para 2, pois contém um componente expresso em 2 e também a antecipação de uma morte literal.</p><p class=\"entry-text\">② destruir mediante a ligação com a crucificação de Cristo, crucificar, um sentido transcendente em extensão de 1, da imitação de Cristo; fig. <span class=\"greek\">οἱ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ἐσταύρωσαν</span> os que pertencem a Cristo Jesus crucificaram a carne com seus desejos pecaminosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:24</a>. Pass.: da cruz de Cristo, <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ἐσταύρωται</span> <span class=\"greek\">κἀγώ</span> <span class=\"greek\">κόσμῳ</span> mediante a qual o mundo foi crucificado para mim, e eu (fui crucificado) para ele, o crente que está inseparavelmente unido ao Senhor morreu na cruz para o tipo de vida que pertence a este mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:14</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐμὸς</span> <span class=\"greek\">ἔρως</span> <span class=\"greek\">ἐσταύρωται</span> minha paixão (pelas coisas mundanas) foi crucificada IRo 7:2.—DELG s.v. <span class=\"greek\">σταυρός</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σταφυλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σταφυλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom.+; inscr., pap., LXX; JosAs 4:4) (um cacho de) uvas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:44</a> (com <span class=\"greek\">σῦκον</span> como Epict. 3, 24, 86; 91; Jos., Bell. 3, 519); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:18</a>. <span class=\"greek\">στ</span>. <span class=\"greek\">παρεστηκυῖα</span> um cacho de uvas maduras (<span class=\"greek\">παρίστημι</span> 2b<span class=\"greek\">γ</span>) 1 Cl 23:4=2 Cl 11:3 (cit. de origem desconhecida).—B. 378. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στάχυς, υος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στάχυς</span>, <span class=\"greek\">υος</span>, <span class=\"greek\">ὁ</span></p><p class=\"entry-text\">① a inflorescência frutífera de um cereal, espiga (de cereal) (Hom. et al.; inscr., pap., LXX; EpArist 63; Philo, Aet. M. 98; Jos., Bell. 2, 112, Ant. 5, 213 al.; Just., D. 119, 3) em nossa lit. somente de trigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:28ab</a>. <span class=\"greek\">τίλλειν</span> (<span class=\"greek\">τοὺς</span>) <span class=\"greek\">στάχυας</span> colher (as) espigas de trigo 2:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:1</a>.</p><p class=\"entry-text\">② <span class=\"greek\">νάρδου</span> <span class=\"greek\">στάχυς</span> (Geopon. 7, 13, 1)=<span class=\"greek\">ναρδοστάχυς</span> a flor da planta aromática nardo, flor do nardo (em forma de espiga de cereal) ApcPt 3, 10.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στάχυς, υος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στάχυς</span>, <span class=\"greek\">υος</span>, <span class=\"greek\">ὁ</span> (várias vezes em PCairZen [III a.C.]; Mitt-Wilck. I/2, 10, 14 [131/130 a.C.]; IG III, 1080, 37; 1095, 19; XII/3, 624; 749; IMagnMai 119, 25; CIL VI 8607) Estáquis, destinatário de uma saudação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:9</a>.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέαρ, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέαρ</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. et al.; pap., LXX, Philo) gordura 1 Cl 4:1 (Gen 4:4); B 2:5 (Is 1:11).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέγη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέγη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">στέγω</span> e o verbete seguinte; Aeschyl., Hdt.+; inscr., pap., LXX; En 14:17; JosAs 3:3; Jos., Ant. 8, 67f; Ar. 15, 7; empréstimo na linguagem rabínica) telhado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4</a> (sobre a remoção da cobertura do telhado cf. Jos., Ant. 14, 459 e FSchulthess, ZNW 21, 1922, 220; HJahnow, ibid. 24, 1925, 155ff [v. JDerrett, Law in the NT, ’70, xv, n. 1]; contra Jahnow: SKrauss, ibid. 25, 1926, 307ff; LFonck, Biblica 6, 1925, 450–54 e PGvanSlogteren, NThT 14, 1925, 361–65. V. também CMcCown, JBL 58, ’39, 213–16). Sobre <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">στ</span>. (<span class=\"greek\">τινός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a> v. <span class=\"greek\">εἰσέρχομαι</span> 1a<span class=\"greek\">γ</span>.—B. 473. DELG s.v. <span class=\"greek\">στέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέγος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέγος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (v. o verbete precedente; Aeschyl. et al.; inscr. [SIG 1179, 20]; EpJer 9 v.l.) teto (Diod S 19, 45, 7; Jos., Ant. 7, 130 al.) <span class=\"greek\">συνάξεις</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">σοὺς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στέγος</span> <span class=\"greek\">σου</span> deves reunir os teus sob teu teto 1 Cl 12:6.—DELG s.v. <span class=\"greek\">στέγω</span>. M-M s.v. <span class=\"greek\">στέγη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέγω</span> inf. aor. <span class=\"greek\">στέξαι</span> (Sir 8:17) (Aeschyl. et al.; inscr., pap.; freq. no sentido de cobrir ou fechar de modo a impedir a entrada de algo indesejável, como água num navio)</p><p class=\"entry-text\">① guardar em segredo, encobrir, passar por alto em silêncio (Eur., Electra 273 <span class=\"greek\">τἀμὰ</span> <span class=\"greek\">ἔπη</span>; Thu. 6, 72, 5; Polyb. 8, 14, 5 <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>; Sir 8:17; Jos., Vi. 225; Field, Notes 177f), assim talvez <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">στέγει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:7</a>, do amor que lança um manto de silêncio sobre o que é desagradável em outra pessoa (Harnack, SBBerlAk 1911, 147; mas v. 2).</p><p class=\"entry-text\">② resistir diante de dificuldades, suportar, aguentar, tolerar (Aeschyl. et al.; Polyb.; Diod S; Plut.; SIG 700, 23; Philo, In Flacc. 64 <span class=\"greek\">στέγειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐνδείας</span>) <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:12</a>; talvez (v. 1) 13:7 (GWhitaker, ‘Love Springs No Leak’: Exp. 8th ser., 21, 1921, 126ff). Abs. (PGrenf I, 1, 18 [II a.C.]; POxy 1775, 10 <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔστεξα</span>, <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔλθῃς</span>) <span class=\"greek\">μηκέτι</span> <span class=\"greek\">στέγων</span> visto que eu já não podia suportá-lo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>; cf. v. 1.—B. 849. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στεῖρα, ας, ἡ</h1><div class=\"entry-meta\"><span>adjetivo feminino; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στεῖρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hom. et al.; IAndrosIsis 82; Philo; LXX; En 98:5; Just.. D. 84, 3 adj. e subst.; B-D-F §43, 1) em nossa lit. incapaz de gerar filhos, estéril, infértil <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:7</a> (sobre as implicações sociais da infertilidade de uma mulher v. Gen 29:31; Lev 20:20f; perspectiva semelhante no mundo gr.: Hdt. 6, 86; mas, ao salientar a retidão do casal [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a>], Lk indica que o pecado não era a causa), v. 36; 23:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a> (Is 54:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a>; 2 Cl 2:1 (Is 54:1); B 13:2 (Gen 25:21).—DELG 1 <span class=\"greek\">στεῖρα</span>. M-M s.v. <span class=\"greek\">στεῖρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέλλω</span> aor. méd. 3 sg. <span class=\"greek\">ἐστείλατο</span> LXX; part. perf. fem. pl. <span class=\"greek\">ἐσταλμέναι</span> 3 Macc 1:19 (Hom. et al. no sentido de ‘preparar, enviar’, etc.; inscr., pap., LXX, Philo; Jos., Ant. 2, 43) em nossa lit., bem como na LXX, somente méd.</p><p class=\"entry-text\">① manter distância, afastar-se, manter-se à parte <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Polyb. 8, 22, 4; cf. Mal 2:5) de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>.</p><p class=\"entry-text\">② esquivar-se de algo, evitar, procurar evitar (Hippocr., <span class=\"greek\">π</span>. <span class=\"greek\">ἀρχ</span>. <span class=\"greek\">ἰητρ</span>. 5 Heib. segundo os cód. <span class=\"greek\">οὔτ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">ἀπόσχοιντο</span> <span class=\"greek\">οὐδενός</span>, <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐπιθυμέουσιν</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">στείλαιντο</span>=‘não se abster de algo [de alimento] … nem evitar aquilo em que têm posto o pensamento’; SEG II, 615, 1 <span class=\"greek\">στέλλεο</span> <span class=\"greek\">Περσεφόνας</span> <span class=\"greek\">ζᾶλον</span>. Mal 2:5 emprega <span class=\"greek\">στ</span>. como paralelo de <span class=\"greek\">φοβεῖσθαι</span>, o que corresponde a Hesíquio: <span class=\"greek\">στέλλεται</span>· <span class=\"greek\">φοβεῖται</span>) <span class=\"greek\">στελλόμενοι</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> evitando ou procurando evitar isto, para que ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:20</a> (assim It., Vulg., Goth., Chrys., Lutero, Calvino e muitos em épocas posteriores).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέμμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. et al.; inscr., pap.; TestSol 7:4 D) grinalda/guirlanda de flores (mas a lã também era necessária para fins religiosos: Herodas 8, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:13</a> (IKosPH [v. <span class=\"greek\">ἀγαθός</span> 2a<span class=\"greek\">α</span>] n.º 37, 29–31: <span class=\"greek\">ἱερεύς</span> … <span class=\"greek\">βοῦς</span> … <span class=\"greek\">στέμμα</span> num sacrifício a Zeus; v. Field, Notes 122).—DELG s.v. <span class=\"greek\">στέφω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στεναγμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στεναγμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">στενάζω</span>; Pind.+; Sb 4949, 12; 5716, 12; PGM 4, 1406; 7, 768; LXX; pseudepígr.; Jos., Bell. 6, 272; Hippol., Ref. 6, 32, 2) manifestação involuntária de grande preocupação ou tensão, suspiro, gemido, lamentação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:34</a> (cf. Ex 2:24 [semelh. Philo, Leg. All. 3, 211]; 6:5) 1 Cl 15:6 (Ps 11:6); Hv 3, 9, 6. Pl. (Diod S 3, 29, 7 <span class=\"greek\">στεναγμοὶ</span> <span class=\"greek\">μεγάλοι</span>) <span class=\"greek\">στεναγμοὶ</span> <span class=\"greek\">ἀλάλητοι</span> (v. <span class=\"greek\">ἀλάλητος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:26</a> (WBieder, TZ 4, ’48, 31–33; JSchniewind, Nachgelassene Reden, ’52, 81–103; ADietzel, TZ 13, ’57, 12–32 [Hodayoth]; EKäsemann, EHaenchen Festschr. ’64, 142–55; MDibelius, Formgeschichte des Evangeliums5 ’66, 82f).—DELG s.v. <span class=\"greek\">στένω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0330-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στενάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στενάζω</span> fut. <span class=\"greek\">στενάξω</span>; 1 aor. <span class=\"greek\">ἐστέναξα</span> (Trag., Demosth. et al.; Sb 2134, 14; LXX; pseudepígr.; Philo)</p><p class=\"entry-text\">① expressar-se involuntariamente diante de uma circunstância indesejável, suspirar, gemer (Herm. Wr. em Stob. I 395, 5 W.=474, 22 Sc.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:2</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span>=neste corpo terreno), 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:17</a>; MPol 2:2; Hv 3, 9, 6; GJs 22:3; AcPl Ha 2, 18. MPol 9:2; <span class=\"greek\">στ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span> suspirar consigo mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:23</a> (cf. Lycophron 1462f <span class=\"greek\">στ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">καρδίᾳ</span>).—Em conexão com uma cura, provavelmente como expressão de poder prestes a agir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:34</a> (cf. PGM 13, 945).</p><p class=\"entry-text\">② expressar descontentamento, queixar-se, extensão fig. de 1: <span class=\"greek\">στ</span>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> gemer contra, queixar-se de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:9</a>.—B. 1131. DELG s.v. <span class=\"greek\">στένω</span>. M-M. TW.</p></section></article>"};
